Here is a sample unit test (LLM generated) to try working with. It compiles and passes on this branch and fails on master.

<details><summary>diff</summary><p>

```diff
diff --git a/src/test/i2p_tests.cpp b/src/test/i2p_tests.cpp
index 4f9c89ee1cf..75c370ee469 100644
--- a/src/test/i2p_tests.cpp
+++ b/src/test/i2p_tests.cpp
@@ -172,4 +172,89 @@ BOOST_AUTO_TEST_CASE(damaged_private_key)
     }
 }

+BOOST_AUTO_TEST_CASE(connect_direct_b32_and_peer_failure)
+{
+    // Valid I2P address; port must be I2P_SAM31_PORT (0).
+    const std::string b32 = "udhdrtrcetjm5sxzskjyr5ztpeszydbh4dpl3pl4utgqqw2v4jna.b32.i2p";
+    CService peer;
+    BOOST_REQUIRE(peer.SetSpecial(b32));
+    BOOST_REQUIRE_EQUAL(peer.GetPort(), 0);
+
+    // 387-byte private key with cert_len=0 so MyDestination() succeeds.
+    std::string privkey(387, '\0');
+    // bytes 385-386 are already 0 (big-endian cert length).
+    const auto key_file = m_args.GetDataDirNet() / "test_i2p_private_key_direct";
+    BOOST_REQUIRE(WriteBinaryFile(key_file, privkey));
+
+    auto interrupt = std::make_shared<CThreadInterrupt>();
+    const CService sam_addr{in6_addr(COMPAT_IN6ADDR_LOOPBACK_INIT), 7656};
+    const Proxy sam_proxy{sam_addr, /*tor_stream_isolation=*/false};
+
+    // Factory that returns a DynSock already pre-loaded with the replies
+    // Connect() will consume. This removes the race between socket creation
+    // and PushBytes.
+    auto make_connect_sock = [](const std::string& result_code) {
+        auto pipes = std::make_shared<DynSock::Pipes>();
+        const std::string hello = "HELLO REPLY RESULT=OK VERSION=3.1\n";
+        const std::string status = "STREAM STATUS RESULT=" + result_code + " MESSAGE=\"test\"\n";
+        pipes->recv.PushBytes(hello.data(), hello.size());
+        pipes->recv.PushBytes(status.data(), status.size());
+        return std::make_pair(std::make_unique<DynSock>(pipes), pipes);
+    };
+
+    std::shared_ptr<DynSock::Pipes> last_connect_pipes;
+    size_t sock_idx{0};
+
+    CreateSock = [&](int, int, int) -> std::unique_ptr<Sock> {
+        ++sock_idx;
+        if (sock_idx == 1) {
+            // Session-creation control socket (private key already on disk).
+            return std::make_unique<StaticContentsSock>(
+                "HELLO REPLY RESULT=OK VERSION=3.1\n"
+                "SESSION STATUS RESULT=OK\n"
+                "a"  // keep socket open
+            );
+        }
+        // Connect-path sockets. The result code is chosen by the caller
+        // before Connect() is invoked; we stash the pipes for later inspection.
+        std::string result = (sock_idx == 2) ? "CANT_REACH_PEER" : "TIMEOUT";
+        auto [sock, pipes] = make_connect_sock(result);
+        last_connect_pipes = pipes;
+        return std::move(sock);
+    };
+
+    i2p::sam::Session session(key_file, sam_proxy, interrupt);
+
+    auto check = [&](const std::string& expected_result) {
+        i2p::Connection conn;
+        bool proxy_error{true};
+        BOOST_CHECK_MESSAGE(!session.Connect(peer, conn, proxy_error),
+                            "Connect must fail");
+        BOOST_CHECK_MESSAGE(!proxy_error,
+                            expected_result + " must set proxy_error=false");
+
+        BOOST_REQUIRE(last_connect_pipes);
+        std::string sent;
+        char buf[4096];
+        ssize_t n;
+        while ((n = last_connect_pipes->send.GetBytes(buf, sizeof(buf))) > 0) {
+            sent.append(buf, n);
+        }
+
+        BOOST_CHECK_MESSAGE(sent.find("NAMING LOOKUP") == std::string::npos,
+                            "NAMING LOOKUP must not appear");
+        BOOST_CHECK_MESSAGE(sent.find("HELLO VERSION MIN=3.1 MAX=3.1") != std::string::npos,
+                            "HELLO expected");
+        BOOST_CHECK_MESSAGE(sent.find("STREAM CONNECT") != std::string::npos,
+                            "STREAM CONNECT expected");
+        BOOST_CHECK_MESSAGE(sent.find("DESTINATION=" + b32) != std::string::npos,
+                            "DESTINATION must be the raw .b32.i2p");
+        BOOST_CHECK_MESSAGE(sent.find("SILENT=false") != std::string::npos,
+                            "SILENT=false expected");
+    };
+
+    check("CANT_REACH_PEER");
+    check("TIMEOUT");
+}
```
</p></details>
